import{createHash}from"crypto";import{existsSync,mkdirSync,readFileSync,writeFileSync}from"fs";import*as os from"os";import*as path from"path";import{fetchArrayBufferWithRetry}from"../utils.js";export let CACHE_DIR=path.join(os.homedir(),".cache","ppu-paddle-ocr");export function cachePathFor(url){let fileName=path.basename(new URL(url).pathname);let digest=createHash("sha256").update(url).digest("hex").slice(0,12);return path.join(CACHE_DIR,digest,fileName)}export async function fetchAndCacheResource(url,verbose){let fileName=path.basename(new URL(url).pathname);let cachePath=cachePathFor(url);if(existsSync(cachePath)){if(verbose)console.log(`[PaddleOcrService] Loading cached resource from: ${cachePath}`);let buf=readFileSync(cachePath);return buf.buffer.slice(buf.byteOffset,buf.byteOffset+buf.byteLength)}console.log(`[PaddleOcrService] Downloading resource: ${fileName}
`+`                 Cached at: ${CACHE_DIR}`);if(verbose)console.log(`[PaddleOcrService] Fetching resource from URL: ${url}`);let arrayBuffer=await fetchArrayBufferWithRetry(url);mkdirSync(path.dirname(cachePath),{recursive:true});writeFileSync(cachePath,Buffer.from(arrayBuffer));return arrayBuffer}